-- Check if transportinfo has a direct link to sensordata via containtransit -> containlink
SELECT COUNT(*) FROM transportinfo t 
JOIN sensordata s ON t.containtransit = s.containlink;

-- Check if transportinfo.vehiclereg matches sensordata.vehsenseref for all rows
SELECT COUNT(*) FROM transportinfo t 
JOIN sensordata s ON t.vehiclereg = s.vehsenseref;
